INSERT INTO `maintenance_forms` (`id`, `form_name`, `form_type`, `form_description`, `form_data`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'Monthly Equipment Inspection', 'INSPECTION', 'Standard monthly inspection checklist', '{\r\n  \"fields\": [\r\n    {\r\n      \"id\": \"inspector_name\",\r\n      \"type\": \"text\",\r\n      \"label\": \"Inspector Name\",\r\n      \"required\": true,\r\n      \"placeholder\": \"Enter your name\"\r\n    },\r\n    {\r\n      \"id\": \"inspection_date\",\r\n      \"type\": \"date\",\r\n      \"label\": \"Inspection Date\",\r\n      \"required\": true\r\n    },\r\n    {\r\n      \"id\": \"device_condition\",\r\n      \"type\": \"radio\",\r\n      \"label\": \"Overall Device Condition\",\r\n      \"required\": true,\r\n      \"options\": [\"Excellent\", \"Good\", \"Fair\", \"Poor\"]\r\n    },\r\n    {\r\n      \"id\": \"physical_damage\",\r\n      \"type\": \"checkbox\",\r\n      \"label\": \"Physical Damage Check\",\r\n      \"required\": false,\r\n      \"options\": [\"Casing Damage\", \"Port Damage\", \"Cable Issues\", \"No Damage\"]\r\n    },\r\n    {\r\n      \"id\": \"performance_check\",\r\n      \"type\": \"radio\",\r\n      \"label\": \"Performance Status\",\r\n      \"required\": true,\r\n      \"options\": [\"Normal\", \"Degraded\", \"Critical\"]\r\n    },\r\n    {\r\n      \"id\": \"temperature\",\r\n      \"type\": \"number\",\r\n      \"label\": \"Device Temperature (°C)\",\r\n      \"required\": false,\r\n      \"placeholder\": \"e.g., 45\"\r\n    },\r\n    {\r\n      \"id\": \"issues_found\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Issues/Observations\",\r\n      \"required\": false,\r\n      \"placeholder\": \"Describe any issues or observations...\"\r\n    },\r\n    {\r\n      \"id\": \"action_required\",\r\n      \"type\": \"radio\",\r\n      \"label\": \"Action Required?\",\r\n      \"required\": true,\r\n      \"options\": [\"No Action\", \"Minor Repair\", \"Major Repair\", \"Replacement\"]\r\n    },\r\n    {\r\n      \"id\": \"photos\",\r\n      \"type\": \"image\",\r\n      \"label\": \"Upload Photos\",\r\n      \"required\": false,\r\n      \"multiple\": true\r\n    }\r\n  ]\r\n}', 1, NULL, '2026-02-04 13:41:51', '2026-02-04 13:41:51'),
(2, 'Equipment Repair Report', 'REPAIR', 'Detailed repair report form', '{\r\n  \"fields\": [\r\n    {\r\n      \"id\": \"technician_name\",\r\n      \"type\": \"text\",\r\n      \"label\": \"Technician Name\",\r\n      \"required\": true\r\n    },\r\n    {\r\n      \"id\": \"repair_date\",\r\n      \"type\": \"date\",\r\n      \"label\": \"Repair Date\",\r\n      \"required\": true\r\n    },\r\n    {\r\n      \"id\": \"problem_description\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Problem Description\",\r\n      \"required\": true,\r\n      \"placeholder\": \"Describe the issue...\"\r\n    },\r\n    {\r\n      \"id\": \"diagnosis\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Diagnosis\",\r\n      \"required\": true,\r\n      \"placeholder\": \"What caused the problem?\"\r\n    },\r\n    {\r\n      \"id\": \"repair_actions\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Repair Actions Taken\",\r\n      \"required\": true,\r\n      \"placeholder\": \"What repairs were performed?\"\r\n    },\r\n    {\r\n      \"id\": \"parts_replaced\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Parts Replaced\",\r\n      \"required\": false,\r\n      \"placeholder\": \"List any parts that were replaced...\"\r\n    },\r\n    {\r\n      \"id\": \"repair_cost\",\r\n      \"type\": \"number\",\r\n      \"label\": \"Repair Cost ($)\",\r\n      \"required\": false,\r\n      \"placeholder\": \"0.00\"\r\n    },\r\n    {\r\n      \"id\": \"repair_status\",\r\n      \"type\": \"radio\",\r\n      \"label\": \"Repair Status\",\r\n      \"required\": true,\r\n      \"options\": [\"Completed\", \"Partially Completed\", \"Failed\", \"Requires Follow-up\"]\r\n    },\r\n    {\r\n      \"id\": \"testing_completed\",\r\n      \"type\": \"checkbox\",\r\n      \"label\": \"Post-Repair Testing\",\r\n      \"required\": true,\r\n      \"options\": [\"Functional Test\", \"Performance Test\", \"Safety Test\"]\r\n    },\r\n    {\r\n      \"id\": \"notes\",\r\n      \"type\": \"textarea\",\r\n      \"label\": \"Additional Notes\",\r\n      \"required\": false\r\n    }\r\n  ]\r\n}', 1, NULL, '2026-02-04 13:41:51', '2026-02-04 13:41:51'),
