--
-- Triggers `maintenance_history`
--
DELIMITER $$
CREATE TRIGGER `calculate_maintenance_duration` BEFORE UPDATE ON `maintenance_history` FOR EACH ROW BEGIN
    IF NEW.completed_at IS NOT NULL AND NEW.started_at IS NOT NULL AND OLD.completed_at IS NULL THEN
        SET NEW.duration_minutes = TIMESTAMPDIFF(MINUTE, NEW.started_at, NEW.completed_at);
    END IF;
END
$$
DELIMITER ;

