--
-- Structure for view `device_network_history`
--
DROP TABLE IF EXISTS `device_network_history`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `device_network_history`  AS SELECT `d`.`mac_address` AS `mac_address`, `d`.`name` AS `name`, `d`.`network_range` AS `network_range`, `n`.`network_name` AS `network_name`, `d`.`status` AS `status`, `d`.`last_seen_at` AS `last_seen_at`, timestampdiff(SECOND,`d`.`last_seen_at`,current_timestamp()) AS `offline_seconds` FROM (`devices` `d` left join `networks` `n` on(`d`.`network_range` = `n`.`network_range`)) ORDER BY `d`.`mac_address` ASC, `d`.`last_seen_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `most_active_devices`
--
DROP TABLE IF EXISTS `most_active_devices`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `most_active_devices`  AS SELECT `p`.`mac_address` AS `mac_address`, `p`.`preferred_name` AS `preferred_name`, `p`.`device_type` AS `device_type`, `p`.`networks_count` AS `networks_count`, `p`.`total_seen_count` AS `total_seen_count`, `p`.`first_seen_at` AS `first_seen_at`, `p`.`last_seen_at` AS `last_seen_at`, timestampdiff(DAY,`p`.`first_seen_at`,`p`.`last_seen_at`) AS `days_tracked` FROM `persistent_devices` AS `p` ORDER BY `p`.`total_seen_count` DESC, `p`.`networks_count` DESC LIMIT 0, 20 ;

-- --------------------------------------------------------

--
-- Structure for view `view_active_alerts`
--
DROP TABLE IF EXISTS `view_active_alerts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_active_alerts`  AS SELECT `ah`.`id` AS `id`, `d`.`name` AS `device_name`, `d`.`ip_address` AS `ip_address`, `ah`.`alert_level` AS `alert_level`, `ah`.`metric_type` AS `metric_type`, `ah`.`metric_value` AS `metric_value`, `ah`.`threshold_value` AS `threshold_value`, `ah`.`message` AS `message`, `ah`.`created_at` AS `created_at` FROM (`alert_history` `ah` join `devices` `d` on(`ah`.`device_id` = `d`.`id`)) WHERE `ah`.`acknowledged` = 0 ORDER BY `ah`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_device_health_summary`
--
DROP TABLE IF EXISTS `view_device_health_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_device_health_summary`  AS SELECT `d`.`id` AS `device_id`, `d`.`name` AS `device_name`, coalesce(`d`.`ip`,'N/A') AS `device_ip`, coalesce(`d`.`online`,0) AS `online`, coalesce(`h`.`health_score`,100) AS `health_score`, coalesce(`h`.`risk_level`,'LOW') AS `risk_level`, coalesce(`h`.`predicted_failure_date`,curdate() + interval 180 day) AS `predicted_failure_date`, coalesce(to_days(`h`.`predicted_failure_date`) - to_days(curdate()),180) AS `days_until_failure`, coalesce(`h`.`confidence_level`,75) AS `confidence_level`, `h`.`last_updated` AS `last_updated` FROM (`devices` `d` left join `device_health_metrics` `h` on(`d`.`id` = `h`.`device_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `view_logs_summary`
--
DROP TABLE IF EXISTS `view_logs_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_logs_summary`  AS SELECT cast(`system_logs`.`created_at` as date) AS `log_date`, `system_logs`.`log_level` AS `log_level`, `system_logs`.`category` AS `category`, count(0) AS `count` FROM `system_logs` WHERE `system_logs`.`created_at` >= current_timestamp() - interval 7 day GROUP BY cast(`system_logs`.`created_at` as date), `system_logs`.`log_level`, `system_logs`.`category` ORDER BY cast(`system_logs`.`created_at` as date) DESC, `system_logs`.`log_level` ASC ;

-- --------------------------------------------------------

--
-- Structure for view `view_maintenance_summary`
--
DROP TABLE IF EXISTS `view_maintenance_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_maintenance_summary`  AS SELECT `d`.`id` AS `device_id`, `d`.`name` AS `device_name`, `d`.`device_type` AS `device_type`, count(`mh`.`id`) AS `total_maintenance`, sum(case when `mh`.`result` = 'success' then 1 else 0 end) AS `successful`, sum(case when `mh`.`result` = 'failed' then 1 else 0 end) AS `failed`, sum(case when `mh`.`result` = 'partial' then 1 else 0 end) AS `partial`, sum(`mh`.`cost`) AS `total_cost`, max(`mh`.`completed_at`) AS `last_maintenance` FROM (`devices` `d` left join `maintenance_history` `mh` on(`d`.`id` = `mh`.`device_id` and `mh`.`completed_at` >= current_timestamp() - interval 30 day)) GROUP BY `d`.`id`, `d`.`name`, `d`.`device_type` ORDER BY count(`mh`.`id`) DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_overdue_maintenance`
--
DROP TABLE IF EXISTS `view_overdue_maintenance`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_overdue_maintenance`  AS SELECT `ms`.`id` AS `schedule_id`, `d`.`id` AS `device_id`, `d`.`name` AS `device_name`, `d`.`ip_address` AS `ip_address`, `ms`.`task_name` AS `task_name`, `ms`.`scheduled_date` AS `scheduled_date`, `ms`.`priority` AS `priority`, `ms`.`assigned_to` AS `assigned_to`, to_days(current_timestamp()) - to_days(`ms`.`scheduled_date`) AS `days_overdue` FROM (`maintenance_schedules` `ms` join `devices` `d` on(`ms`.`device_id` = `d`.`id`)) WHERE `ms`.`status` = 'pending' AND `ms`.`scheduled_date` < current_timestamp() ORDER BY to_days(current_timestamp()) - to_days(`ms`.`scheduled_date`) DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_recent_metrics`
--
DROP TABLE IF EXISTS `view_recent_metrics`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_recent_metrics`  AS SELECT `sm`.`id` AS `id`, `sm`.`cpu_usage` AS `cpu_usage`, `sm`.`ram_usage` AS `ram_usage`, `sm`.`temperature` AS `temperature`, `sm`.`network_total_speed` AS `network_total_speed`, `sm`.`recorded_at` AS `recorded_at` FROM `system_metrics` AS `sm` WHERE `sm`.`recorded_at` >= current_timestamp() - interval 24 hour ORDER BY `sm`.`recorded_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_risk_dashboard`
--
DROP TABLE IF EXISTS `view_risk_dashboard`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_risk_dashboard`  AS SELECT coalesce(`device_health_metrics`.`risk_level`,'LOW') AS `risk_level`, count(0) AS `device_count`, coalesce(avg(`device_health_metrics`.`health_score`),0) AS `avg_health_score`, min(`device_health_metrics`.`predicted_failure_date`) AS `earliest_failure`, coalesce(avg(`device_health_metrics`.`confidence_level`),0) AS `avg_confidence` FROM `device_health_metrics` GROUP BY `device_health_metrics`.`risk_level` ;

-- --------------------------------------------------------

--
-- Structure for view `view_upcoming_maintenance`
--
DROP TABLE IF EXISTS `view_upcoming_maintenance`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_upcoming_maintenance`  AS SELECT `ms`.`id` AS `schedule_id`, `d`.`id` AS `device_id`, `d`.`name` AS `device_name`, `d`.`ip_address` AS `ip_address`, `d`.`device_type` AS `device_type`, `ms`.`task_name` AS `task_name`, `ms`.`task_category` AS `task_category`, `ms`.`scheduled_date` AS `scheduled_date`, `ms`.`priority` AS `priority`, `ms`.`status` AS `status`, `ms`.`assigned_to` AS `assigned_to`, to_days(`ms`.`scheduled_date`) - to_days(current_timestamp()) AS `days_until` FROM (`maintenance_schedules` `ms` join `devices` `d` on(`ms`.`device_id` = `d`.`id`)) WHERE `ms`.`status` in ('pending','in_progress') AND `ms`.`scheduled_date` <= current_timestamp() + interval 7 day ORDER BY `ms`.`scheduled_date` ASC ;

-- --------------------------------------------------------

--
-- Structure for view `v_reports_list`
--
DROP TABLE IF EXISTS `v_reports_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_reports_list`  AS SELECT `mr`.`id` AS `id`, `mr`.`report_number` AS `report_number`, `mr`.`report_title` AS `report_title`, `mr`.`report_type` AS `report_type`, `mr`.`report_status` AS `report_status`, `mr`.`maintenance_date` AS `maintenance_date`, `mr`.`technician_name` AS `technician_name`, `mr`.`overall_condition` AS `overall_condition`, `mr`.`docx_file` AS `docx_file`, `mr`.`pdf_file` AS `pdf_file`, `mr`.`generated_at` AS `generated_at`, `d`.`name` AS `device_name`, `d`.`ip_address` AS `ip_address`, `d`.`device_type` AS `device_type`, `et`.`type_name` AS `equipment_type_name`, `et`.`type_code` AS `equipment_type_code`, `ms`.`task_name` AS `maintenance_task_name` FROM (((`maintenance_reports` `mr` left join `devices` `d` on(`mr`.`device_id` = `d`.`id`)) join `equipment_types` `et` on(`mr`.`equipment_type_id` = `et`.`id`)) left join `maintenance_schedules` `ms` on(`mr`.`maintenance_schedule_id` = `ms`.`id`)) ORDER BY `mr`.`generated_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_reports_summary`
--
DROP TABLE IF EXISTS `v_reports_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_reports_summary`  AS SELECT `et`.`type_name` AS `type_name`, `et`.`type_code` AS `type_code`, count(`mr`.`id`) AS `total_reports`, sum(case when `mr`.`overall_condition` = 'good' then 1 else 0 end) AS `good_condition`, sum(case when `mr`.`overall_condition` = 'fair' then 1 else 0 end) AS `fair_condition`, sum(case when `mr`.`overall_condition` = 'poor' then 1 else 0 end) AS `poor_condition`, sum(case when `mr`.`overall_condition` = 'critical' then 1 else 0 end) AS `critical_condition`, sum(case when `mr`.`report_type` = 'ai_prediction' then 1 else 0 end) AS `ai_generated`, sum(case when `mr`.`report_type` = 'scheduled_maintenance' then 1 else 0 end) AS `scheduled_generated` FROM (`equipment_types` `et` left join `maintenance_reports` `mr` on(`et`.`id` = `mr`.`equipment_type_id`)) GROUP BY `et`.`id`, `et`.`type_name`, `et`.`type_code` ;

